using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace McpServer;

/// <summary>
/// MCP tools are discovered by the SDK via the [McpServerToolType] attribute on the class
/// and [McpServerTool] on each method. The SDK uses DI to resolve constructor parameters.
/// </summary>
[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _httpClient;

    // The SDK resolves this via DI — HttpClient comes from IHttpClientFactory
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get current weather for a city")]
    public async Task<string> GetWeather(
        [Description("City name, e.g. 'London'")] string city,
        [Description("Units: 'metric' or 'imperial'")] string units = "metric")
    {
        // Example using Open-Meteo (free, no API key needed)
        var geo = await _httpClient.GetFromJsonAsync<GeoResponse>(
            $"https://geocoding-api.open-meteo.com/v1/search?name={Uri.EscapeDataString(city)}&count=1");

        if (geo?.Results is not [var location, ..])
            return $"City '{city}' not found.";

        var tempUnit = units == "imperial" ? "fahrenheit" : "celsius";
        var weather = await _httpClient.GetFromJsonAsync<WeatherResponse>(
            $"https://api.open-meteo.com/v1/forecast?latitude={location.Latitude}&longitude={location.Longitude}&current_weather=true&temperature_unit={tempUnit}");

        var cw = weather!.CurrentWeather;
        return $"Weather in {location.Name}: {cw.Temperature}°{(units == "imperial" ? "F" : "C")}, wind {cw.WindSpeed} km/h";
    }

    [McpServerTool, Description("Get a 3-day weather forecast for a city")]
    public async Task<string> GetForecast(
        [Description("City name")] string city)
    {
        var geo = await _httpClient.GetFromJsonAsync<GeoResponse>(
            $"https://geocoding-api.open-meteo.com/v1/search?name={Uri.EscapeDataString(city)}&count=1");

        if (geo?.Results is not [var location, ..])
            return $"City '{city}' not found.";

        var forecast = await _httpClient.GetFromJsonAsync<ForecastResponse>(
            $"https://api.open-meteo.com/v1/forecast?latitude={location.Latitude}&longitude={location.Longitude}&daily=temperature_2m_max,temperature_2m_min&forecast_days=3&timezone=auto");

        var lines = forecast!.Daily.Time.Select((date, i) =>
            $"{date}: {forecast.Daily.Min[i]}°C – {forecast.Daily.Max[i]}°C");

        return $"3-day forecast for {location.Name}:\n{string.Join("\n", lines)}";
    }
}

// DTOs for the Open-Meteo API
public record GeoResponse(
    [property: JsonPropertyName("results")] GeoResult[]? Results);

public record GeoResult(
    [property: JsonPropertyName("name")] string Name,
    [property: JsonPropertyName("latitude")] double Latitude,
    [property: JsonPropertyName("longitude")] double Longitude);

public record WeatherResponse(
    [property: JsonPropertyName("current_weather")] CurrentWeather CurrentWeather);

public record CurrentWeather(
    [property: JsonPropertyName("temperature")] double Temperature,
    [property: JsonPropertyName("windspeed")] double WindSpeed);

public record ForecastResponse(
    [property: JsonPropertyName("daily")] DailyForecast Daily);

public record DailyForecast(
    [property: JsonPropertyName("time")] string[] Time,
    [property: JsonPropertyName("temperature_2m_max")] double[] Max,
    [property: JsonPropertyName("temperature_2m_min")] double[] Min);

using Microsoft.Extensions.DependencyInjection;
using ModelContextProtocol.Server;

var builder = McpServerBuilder.ForStdioTransport();

builder.ServerInfo = new() { Name = "weather-server", Version = "1.0.0" };

// Register HttpClient via DI — the SDK injects it into tool constructors
builder.Services.AddHttpClient<McpServer.WeatherTools>();

// WithToolsFromAssembly discovers all [McpServerToolType] classes automatically
builder.WithToolsFromAssembly();

await using var server = builder.Build();
await server.RunAsync();

